this.dataset.properties = properties.value.trim();

for (const column of window.threadPane.columns) {
  // Skip this column if it's hidden.
  if (column.hidden) {
    continue;
  }
  const cell = this.querySelector(`.${column.id.toLowerCase()}-column`);
  const textIndex = textColumns.indexOf(column.id);

  // Special case for the subject column.
  if (column.id == "subjectCol") {
    const div = cell.querySelector(".subject-line");

    // Indent child message of this thread.
    div.style.setProperty(
      "--thread-level",
      window.gViewWrapper.showGroupedBySort ? 0 : threadLevel.value
    );

    const imageFluentID = this.#getMessageIndicatorString(propertiesSet);
    const image = div.querySelector("img");
    if (imageFluentID && !isDummyRow) {
      document.l10n.setAttributes(image, imageFluentID);
    } else {
      image.removeAttribute("data-l10n-id");
      image.alt = "";
    }

    let subjectText = cellTexts[textIndex];
    if (isDummyRow) {
      // Big assumption here that the total and unread are always the last 2
      // elements of the array. Tests will ensure that.
      const unread = Number(cellTexts.at(-2));
      const total = Number(cellTexts.at(-1));
      subjectText += unread ? ` (${unread}/${total})` : ` (${total})`;
    }

    const span = div.querySelector("span");
    span.textContent = subjectText;
    const twistyButton = cell.querySelector("button.twisty");
    if (twistyButton) {
      if (this.classList.contains("children")) {
        document.l10n.setAttributes(
          twistyButton,
          this.classList.contains("collapsed")
            ? "tree-list-view-row-expand-thread-button"
            : "tree-list-view-row-collapse-thread-button"
        );
        twistyButton.ariaExpanded = String(
          !this.classList.contains("collapsed")
        );
      } else {
        twistyButton.removeAttribute("data-l10n-id");
        twistyButton.removeAttribute("aria-expanded");
        twistyButton.removeAttribute("aria-label");
      }
    }
    document.l10n.setAttributes(cell, column.l10n.cell, {
      title: subjectText,
    });
    ariaLabelPromises.push(subjectText);
